import{createInputController}from"../../shared/input.js";import{AMBER_WIDTH,FOLLOW_X,GATES,LEAD_X,ROOF_Y,ROUTE_MS,TUTORIAL_MS,corridorAt,createGame,setHeld,summarize,updateGame}from"./state.js";const $=id=>document.getElementById(id),canvas=$("sky"),ctx=canvas.getContext("2d"),gameView=$("game"),result=$("result"),prompt=$("prompt"),time=$("time"),chain=$("chain"),safety=$("safety"),score=$("score");const reduced=matchMedia("(prefers-reduced-motion: reduce)").matches;document.body.dataset.motion=reduced?"reduced":"full";let state,tutorial,last,frame,paused=false,shown=false;function shiftAt(x){return reduced?.44-(x<=FOLLOW_X?state.followerY:x>=LEAD_X?state.leadY:state.followerY+(state.leadY-state.followerY)*(x-FOLLOW_X)/(LEAD_X-FOLLOW_X)):0}function polygon(points,fill){ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fillStyle=fill;ctx.fill()}function bandPoints(extra=0){const top=[],bottom=[];for(let i=0;i<=24;i++){const x=i/24,b=corridorAt(state.elapsed,x);top.push([x*640,(b.center-b.half-extra+shiftAt(x))*480]);bottom.unshift([x*640,(b.center+b.half+extra+shiftAt(x))*480])}return top.concat(bottom)}function hatch(points,color,space=22){ctx.save();polygon(points,color+"22");ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.clip();ctx.strokeStyle=color;ctx.lineWidth=2;for(let x=-480;x<700;x+=space){ctx.beginPath();ctx.moveTo(x,480);ctx.lineTo(x+480,0);ctx.stroke()}ctx.restore()}function craft(x,y,label){const X=x*640,Y=(reduced?.44:y)*480;ctx.fillStyle="#f7f5df";ctx.strokeStyle="#03141d";ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(X+17,Y);ctx.lineTo(X-10,Y-10);ctx.lineTo(X-17,Y);ctx.lineTo(X-10,Y+10);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle="#03141d";ctx.font="bold 12px monospace";ctx.fillText(label,X-4,Y+4)}function drawGate(gate){const x=(LEAD_X+(gate.at-state.elapsed)/7000)*640;if(x<-25||x>665)return;const s=shiftAt(x/640),r=shiftAt(LEAD_X),top=(gate.center-gate.half+s)*480,bottom=(gate.center+gate.half+s)*480;ctx.fillStyle="#ffc857";ctx.fillRect(x-5,0,10,top);ctx.fillRect(x-5,bottom,10,(ROOF_Y+r)*480-bottom);ctx.strokeStyle="#66f2ad";ctx.lineWidth=4;ctx.strokeRect(x-8,top,16,bottom-top)}function draw(){const s=shiftAt(LEAD_X);ctx.clearRect(0,0,640,480);ctx.fillStyle="#0b3044";ctx.fillRect(0,0,640,480);hatch(bandPoints(AMBER_WIDTH),"#ffc857",28);hatch(bandPoints(),"#66f2ad",24);ctx.fillStyle="#7c1730";ctx.fillRect(0,(ROOF_Y+s)*480,640,480);ctx.strokeStyle="#ff466d";ctx.lineWidth=6;ctx.setLineDash([15,9]);ctx.beginPath();ctx.moveTo(0,(ROOF_Y+s)*480);ctx.lineTo(640,(ROOF_Y+s)*480);ctx.stroke();ctx.setLineDash([]);GATES.forEach(drawGate);craft(FOLLOW_X,state.followerY,"B");craft(LEAD_X,state.leadY,"A");time.textContent=((ROUTE_MS-state.elapsed)/1000).toFixed(1);chain.textContent=state.chain;safety.textContent=(state.elapsed?Math.round(state.safeTime/state.elapsed*100):0)+"%";score.textContent=Math.round(state.score)}function finish(){if(shown)return;shown=true;const report=summarize(state),failed=report.reason==="roofline";$("result-title").textContent=failed?"Roofline crossed":"Pass complete";$("announcement").textContent="Formation held: "+report.formation+"%. Safe gates: "+report.gates+". Roofline breaches: "+report.breaches+".";$("final-score").textContent=report.score;$("final-gates").textContent=report.gates+" / "+report.totalGates;gameView.hidden=true;result.hidden=false;result.focus()}function tick(now){if(!last)last=now;const delta=paused?0:now-last;last=now;if(!paused){if(tutorial<TUTORIAL_MS){tutorial+=delta;prompt.textContent=tutorial<TUTORIAL_MS?"HOLD TO RISE / RELEASE TO SETTLE":"CORRIDOR OPEN"}else updateGame(state,delta)}draw();if(state.ended)finish();else frame=requestAnimationFrame(tick)}function onInput(input){const pointer=input.source==="pointer"&&input.action==="position",keyboard=input.source==="keyboard"&&(input.action==="activate"||input.action==="up");if(input.action==="reset-input"){setHeld(state,false);canvas.ariaPressed="false"}if(!pointer&&!keyboard)return;if(input.phase==="start"){setHeld(state,true);canvas.ariaPressed="true";prompt.textContent="RISING — RELEASE EARLY"}if(input.phase==="end"||input.phase==="cancel"){setHeld(state,false);canvas.ariaPressed="false";prompt.textContent="SETTLING — HOLD TO LIFT"}}function start(){cancelAnimationFrame(frame);state=createGame();tutorial=last=0;shown=false;canvas.ariaPressed="false";result.hidden=true;gameView.hidden=false;frame=requestAnimationFrame(tick);canvas.focus({preventScroll:true})}createInputController(canvas,{onInput});document.addEventListener("visibilitychange",()=>{paused=document.hidden;last=0;if(paused){setHeld(state,false);canvas.ariaPressed="false"}});$("retry").addEventListener("click",start);start();
